export const PHOTOS_TEXT = formConfig.consents[1].text;

export type RegistrationReply =
  | { kind: "json"; status: number; body: unknown }
  | { kind: "network-error" };

export interface RecordedRequest {
  url: string;
  method: string;
  body: unknown;
}

/**
 * Replaces fetch with a test double of the backend contract: GET /api/form-config answers the
 * configuration above, POST /api/registrations answers the given reply. Every call is recorded.
 */
export function installFakeBackend(registrationReply: RegistrationReply) {
  const requests: RecordedRequest[] = [];
  const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url =
      typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;
    const method = (
      init?.method ?? (typeof input === "object" && "method" in input ? input.method : "GET")
    ).toUpperCase();
    const rawBody = init?.body;
    let body: unknown = undefined;
    if (typeof rawBody === "string") {
      try {
        body = JSON.parse(rawBody);
      } catch {
        body = rawBody;
      }
    }
    requests.push({ url, method, body });
    const path = new URL(url, "http://localhost").pathname;
    if (path === "/api/form-config" && method === "GET") {
      return jsonResponse(200, formConfig);
    }
    if (path === "/api/registrations" && method === "POST") {
      if (registrationReply.kind === "network-error") {
        throw new TypeError("Failed to fetch");
      }
      return jsonResponse(registrationReply.status, registrationReply.body);
    }
    return jsonResponse(404, { message: "Not found", fieldErrors: [] });
  });
  vi.stubGlobal("fetch", fetchMock);
  return {
    requests,
    registrationRequests: () =>
      requests.filter(
        (r) => r.method === "POST" && new URL(r.url, "http://localhost").pathname === "/api/registrations",
      ),
  };
}

function jsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

export const acceptedExternal = {
  kind: "json" as const,
  status: 201,
  body: {
    id: "7d1c6a52-3f0e-4b8e-9d55-2a4f0c9b1e11",
    type: "EXTERNAL",
    firstName: "Ana",
    lastName: "Novak",
    options: [
      { id: "ws-ai", name: "Workshop: AI in practice", category: "WORKSHOP" },
      { id: "meal-lunch", name: "Lunch", category: "MEAL" },
    ],
    registeredAt: "2026-10-19T12:00:00.123Z",
  },
};

import { fireEvent, screen } from "@testing-library/react";
import { PRIVACY_TEXT } from "./fakeBackend";

/** Waits for the form configuration and chooses a registration type (ui.md). */
export async function chooseType(type: "External participant" | "Student") {
  const radio = await screen.findByRole("radio", { name: type });
  fireEvent.click(radio);
}

export function textbox(name: string): HTMLInputElement {
  return screen.getByRole("textbox", { name }) as HTMLInputElement;
}

export function type(name: string, value: string) {
  fireEvent.change(textbox(name), { target: { value } });
}

export function check(name: string) {
  fireEvent.click(screen.getByRole("checkbox", { name }));
}

/** Names of every textbox on the page. */
export function textboxNames(): string[] {
  return screen
    .queryAllByRole("textbox")
    .map((element) => element.getAttribute("aria-label") ?? labelOf(element));
}

function labelOf(element: HTMLElement): string {
  const labels = (element as HTMLInputElement).labels;
  return labels && labels.length > 0 ? (labels[0].textContent ?? "").trim() : "";
}

/** Fills a valid external submission: fields, two options, the mandatory consent, captcha. */
export async function fillValidExternal() {
  await chooseType("External participant");
  type("First name", "Ana");
  type("Last name", "Novak");
  type("Email", "ana.novak@example.com");
  type("Organization / institution", "Institut Jozef Stefan");
  check("Workshop: AI in practice");
  check("Lunch");
  check(PRIVACY_TEXT);
  check("I am not a robot (test mode)");
}

export function submit() {
  fireEvent.click(screen.getByRole("button", { name: "Register" }));
}

