import { expect, type Page } from "@playwright/test";
import { conferenceConfig, type ConferenceOption } from "./stack";

/** Opens the page and chooses the registration type (ui.md). */
export async function openForm(page: Page, type: "External participant" | "Student") {
  await page.goto("/");
  await page.getByRole("radio", { name: type, exact: true }).check();
}

export async function fill(page: Page, fields: Record<string, string>) {
  for (const [name, value] of Object.entries(fields)) {
    await page.getByRole("textbox", { name, exact: true }).fill(value);
  }
}

export async function selectOptions(page: Page, options: ConferenceOption[]) {
  for (const option of options) {
    await page.getByRole("checkbox", { name: option.name, exact: true }).check();
  }
}

/** Gives every mandatory consent and passes the test-mode reCAPTCHA. */
export async function consentAndCaptcha(page: Page) {
  for (const consent of conferenceConfig().consents.filter((c) => c.mandatory)) {
    await page.getByRole("checkbox", { name: consent.text, exact: true }).check();
  }
  await page.getByRole("checkbox", { name: "I am not a robot (test mode)", exact: true }).check();
}

export async function register(page: Page) {
  await page.getByRole("button", { name: "Register", exact: true }).click();
}

export async function expectConfirmation(page: Page, texts: string[]) {
  const confirmation = page.getByRole("status");
  await expect(confirmation.getByRole("heading", { name: "Registration received" })).toBeVisible();
  for (const text of texts) {
    await expect(confirmation).toContainText(text);
  }
  await expect(page.getByRole("button", { name: "Register", exact: true })).toHaveCount(0);
}

import { expect, test } from "@playwright/test";
import {
  attachment,
  awaitMessage,
  clearMailpit,
  conferenceConfig,
  jsonCopy,
  onePerCategory,
  optionIdsOf,
  optionsFor,
  organizer,
  registrationsByEmail,
  uniqueEmail,
} from "./support/stack";
import { consentAndCaptcha, expectConfirmation, fill, openForm, register, selectOptions } from "./support/form";

test.beforeAll(async () => {
  await clearMailpit();
});

test("E2E-01 external participant registers (AC-001-01, AC-001-08, AC-004-01, AC-005-01, AC-005-02, AC-006-01, AC-007-01, AC-007-02)", async ({
  page,
}) => {
  const email = uniqueEmail("e2e.external");
  const options = onePerCategory("EXTERNAL");
  expect(options.map((o) => o.category)).toEqual(["WORKSHOP", "EVENT", "MEAL", "OTHER"]);

  await openForm(page, "External participant");
  await expect(page.getByRole("textbox")).toHaveCount(4);
  await fill(page, {
    "First name": "Maja",
    "Last name": "Zupan",
    Email: email,
    "Organization / institution": "Arnes",
  });
  await selectOptions(page, options);
  await consentAndCaptcha(page);
  await register(page);

  await expectConfirmation(page, ["Maja", "Zupan", ...options.map((o) => o.name)]);

  const rows = registrationsByEmail(email);
  expect(rows).toHaveLength(1);
  const row = rows[0];
  expect(row).toMatchObject({
    type: "EXTERNAL",
    first_name: "Maja",
    last_name: "Zupan",
    organization: "Arnes",
  });
  expect(optionIdsOf(row.id).sort()).toEqual(options.map((o) => o.id).sort());

  const copy = jsonCopy(row.id);
  expect(JSON.parse(copy.toString("utf8"))).toMatchObject({ id: row.id, type: "EXTERNAL", email });

  const confirmation = await awaitMessage(email, "Maja");
  expect(confirmation.Text).toContain(conferenceConfig().conferenceName);
  for (const address of organizer().emails) {
    const notification = await awaitMessage(address, row.id);
    expect(await attachment(notification, `registration-${row.id}.json`)).toEqual(copy);
  }
});

test("E2E-02 student registers (AC-002-01, AC-002-07, AC-004-01)", async ({ page }) => {
  const email = uniqueEmail("e2e.student");
  const options = onePerCategory("STUDENT");

  await openForm(page, "Student");
  await expect(page.getByRole("textbox")).toHaveCount(6);
  for (const name of [
    "First name",
    "Last name",
    "Email",
    "Study institution",
    "Study programme",
    "Student ID",
  ]) {
    await expect(page.getByRole("textbox", { name, exact: true })).toBeVisible();
  }
  for (const option of conferenceConfig().options) {
    const shown = optionsFor("STUDENT").some((o) => o.id === option.id);
    await expect(page.getByRole("checkbox", { name: option.name, exact: true })).toHaveCount(
      shown ? 1 : 0,
    );
  }

  await fill(page, {
    "First name": "Nik",
    "Last name": "Horvat",
    Email: email,
    "Study institution": "Univerza v Mariboru",
    "Study programme": "Informatika",
    "Student ID": "E1234567",
  });
  await selectOptions(page, options);
  await consentAndCaptcha(page);
  await register(page);

  await expectConfirmation(page, ["Nik", "Horvat", ...options.map((o) => o.name)]);
  const rows = registrationsByEmail(email);
  expect(rows).toHaveLength(1);
  expect(rows[0]).toMatchObject({
    type: "STUDENT",
    study_institution: "Univerza v Mariboru",
    study_programme: "Informatika",
    student_id: "E1234567",
  });
  await awaitMessage(email, "Nik");
  for (const address of organizer().emails) {
    await awaitMessage(address, rows[0].id);
  }
});

import { expect, test } from "@playwright/test";
import { conferenceConfig, onePerCategory, registrationsByEmail, uniqueEmail } from "./support/stack";
import { consentAndCaptcha, fill, openForm, register, selectOptions } from "./support/form";

test("E2E-03 field errors are shown next to the fields (AC-004-02, AC-004-03)", async ({ page }) => {
  const email = uniqueEmail("e2e.errors");
  const posted: string[] = [];
  page.on("request", (request) => {
    if (request.method() === "POST" && new URL(request.url()).pathname === "/api/registrations") {
      posted.push(request.url());
    }
  });

  await openForm(page, "External participant");
  await fill(page, {
    "Last name": "Kovač",
    Email: "not-an-email@",
    "Organization / institution": "Arnes",
  });
  await selectOptions(page, onePerCategory("EXTERNAL").slice(0, 1));
  await consentAndCaptcha(page);
  await register(page);

  const firstName = page.getByRole("textbox", { name: "First name", exact: true });
  const emailBox = page.getByRole("textbox", { name: "Email", exact: true });
  await expect(firstName).toHaveAttribute("aria-invalid", "true");
  await expect(firstName).toHaveAttribute("aria-describedby", "error-firstName");
  await expect(page.locator("#error-firstName")).not.toBeEmpty();
  await expect(emailBox).toHaveAttribute("aria-invalid", "true");
  await expect(emailBox).toHaveAttribute("aria-describedby", "error-email");
  await expect(page.locator("#error-email")).not.toBeEmpty();
  expect(posted).toHaveLength(0);

  const inactive = conferenceConfig().options.find((o) => !o.active);
  expect(inactive).toBeDefined();
  await page.route("**/api/registrations", async (route) => {
    const body = JSON.parse(route.request().postData() ?? "{}");
    body.optionIds = [...(body.optionIds ?? []), inactive!.id];
    await route.continue({ postData: JSON.stringify(body) });
  });
  await fill(page, { "First name": "Tina", Email: email });
  await register(page);

  await expect(page.locator("#error-optionIds")).not.toBeEmpty();
  await expect(page.locator('[aria-describedby~="error-optionIds"]')).toHaveCount(1);
  expect(posted).toHaveLength(1);
  await expect(page.getByRole("status")).toHaveCount(0);
  await expect(firstName).toHaveValue("Tina");
  await expect(page.getByRole("textbox", { name: "Last name", exact: true })).toHaveValue("Kovač");
  await expect(emailBox).toHaveValue(email);
  expect(registrationsByEmail(email)).toHaveLength(0);
});

