                    .permitAll()
                    .requestMatchers(HttpMethod.GET, OrganizerHttpsOnlyFilter.EXPORT_PATH)
                    .hasRole(ORGANIZER)
                    .anyRequest()
                    .denyAll());
    return http.build();
  }

