/**
 * Covers AC-003-03, AC-007-01, AC-008-01 and SR-01 details of the adapters (phase 5 survivors).
 */
class AdapterDetailsTest {

  @TempDir Path dir;

  @Test
  void AC_007_01_notificationIsSentFromTheConfiguredAddressWithTheRegistrationTime()
      throws Exception {
    MimeMessage message =
        new OrganizerMailComposer(
                new JavaMailSenderImpl(), "from@konferenca.test", "Konf", List.of("o@k.si"))
            .compose(OrganizerMailComposerTest.student())
            .get(0);

    assertThat(message.getFrom()).containsExactly(new InternetAddress("from@konferenca.test"));
    assertThat(OrganizerMailComposerTest.text(message))
        .contains("Registered at: 2026-10-19T12:00:00.123Z");
  }

  @Test
  void AC_008_01_everyCellIsQuotePrefixedText() throws Exception {
    byte[] xlsx =
        new ExcelWorkbookWriter()
            .write(
                List.of(
                    si.konferenca.registration.infrastructure.export.ExcelWorkbookWriterTest
                        .external("=1+1")));

    try (XSSFWorkbook workbook = new XSSFWorkbook(new ByteArrayInputStream(xlsx))) {
      Sheet sheet = workbook.getSheet("Registrations");
      for (Row row : sheet) {
        row.forEach(cell -> assertThat(cell.getCellStyle().getQuotePrefixed()).isTrue());
      }
    }
  }

  @Test
  void AC_003_03_unknownPropertiesInsideConsentsOrOptionsAreConfigurationErrors()
      throws Exception {
    Path consent = dir.resolve("consent.json");
    Files.writeString(
        consent,
        "{\"conferenceName\":\"C\",\"consents\":[{\"id\":\"p\",\"text\":\"T\",\"mandatory\":true,"
            + "\"preselected\":true}],\"options\":[]}",
        StandardCharsets.UTF_8);
    Path option = dir.resolve("option.json");
    Files.writeString(
